use super::*;
use crate::pet_runtime::{authority_store::delegation_branch::Action as BranchAction,delegation::State as Branch,Repository,leases::DrainOutcome};
fn queued(s:&Setup,r:&crate::pet_runtime::messages::Receipt)->Record{let g=own_draft(s,r);let a=approved(s,&g,child_budget(r),nonce().unwrap());let cert=s.a.certify(&a,&g,crate::assistant_memory::now()).unwrap();current_store(s).enqueue_certified(&cert,crate::assistant_memory::now()).unwrap().record}
fn review(s:&Setup,p:&Record,r:&crate::pet_runtime::messages::Receipt,action:BranchAction)->model::Result<crate::pet_runtime::authority_store::delegation_branch::Candidate>{Authority::existing(&s.f.path.join("authority")).unwrap().prepare_delegation_branch(p.clone(),&p.admissions[0].spec.decision_id,&r.envelope().message_id,action,crate::assistant_memory::now())}
fn project_cancel(s:&Setup,g:&Record)->Record{let st=current_store(s);let g=st.read_control(&g.id,&g.spec.owner.pet_id).unwrap();crate::pet_runtime::authority_store::mutate_with_authority(&st,&s.f.path.join("authority"),&g.id,&g.spec.owner.pet_id,&g.revision,"exact-branch-stop".into(),Action::Cancel,crate::assistant_memory::now()).unwrap().record}
#[test]fn branch_cancel_fences_one_original_worker_and_retains_escrow_until_its_actual_drain(){
 let s=Setup::new();let(p,source)=pool(&s,"ai_ollama",2,budget());let r1=source.send_message(&p,&approve(&s,&p,&source,0),crate::assistant_memory::now(),||s.observe()).unwrap();let r2=source.send_message(&p,&approve(&s,&p,&source,1),crate::assistant_memory::now(),||s.observe()).unwrap();
 let q1=queued(&s,&r1);let(g1,o1)=crate::pet_runtime::deterministic_runtime_tests::owned(&s.f,&s.a,&q1,&s.main);let worker=o1.worker(crate::assistant_memory::now()).unwrap();
 let q2=queued(&s,&r2);let c=review(&s,&p,&r1,BranchAction::Cancel).unwrap();let result=c.confirm(crate::assistant_memory::now(),Arc::new(||true)).unwrap();assert!(matches!(result.view.reservations[0].state,Branch::CancelRequested{..}));assert!(matches!(result.view.reservations[1].state,Branch::Bound{..}));assert_eq!(result.view.grant_hash,model::fingerprint(&serde_json::from_slice::<crate::pet_runtime::authority::GrantEnvelope>(&s.bytes(&p)).unwrap().body).unwrap());assert_eq!(result.view.held.unwrap().tool_calls,2);assert!(result.stop.unwrap().binding.matches(&g1.admissions[0].spec));
 assert!(!worker.current(crate::assistant_memory::now()));assert!(o1.worker(crate::assistant_memory::now()).is_err());assert!(o1.drain(DrainOutcome::Confirmed).is_err());assert!(review(&s,&p,&r1,BranchAction::Reconcile).is_err());
 let phase:Value=serde_json::from_slice(&s.bytes(&g1)).unwrap();assert_eq!(phase["body"]["phase"],"draining");assert_eq!(serde_json::from_slice::<Value>(&s.bytes(&p)).unwrap()["body"]["schemaVersion"],20);
 assert!(Authority::existing(&s.f.path.join("authority")).unwrap().prepare_delegation_branch(p.clone(),&p.admissions[0].spec.decision_id,&r1.envelope().message_id,BranchAction::Reconcile,r1.envelope().deadline_at+1).is_err());
 let current=project_cancel(&s,&g1);assert_eq!(current.state,State::Stopping);assert!(review(&s,&p,&r1,BranchAction::Reconcile).is_err());drop(worker);
 let drain=o1.drain(DrainOutcome::Confirmed).unwrap();let end=current_store(&s).drain_owned(&s.a,&drain,crate::assistant_memory::now()).unwrap();assert_eq!(end.record.state,State::Cancelled);
 let settle=review(&s,&p,&r1,BranchAction::Reconcile).unwrap();let v=settle.confirm(crate::assistant_memory::now(),Arc::new(||true)).unwrap().view;assert_eq!(v.grant_hash,model::fingerprint(&serde_json::from_slice::<crate::pet_runtime::authority::GrantEnvelope>(&s.bytes(&p)).unwrap().body).unwrap());assert_eq!(v.held.unwrap().tool_calls,1);assert_eq!(v.consumed.unwrap(),Allowance::default());assert_eq!(v.unknown.unwrap(),Allowance::default());assert!(matches!(v.reservations[1].state,Branch::Bound{..}));assert!(s.a.verify_queued(&q2,crate::assistant_memory::now()).is_ok());
 let bytes=s.bytes(&p);settle.confirm(r1.envelope().deadline_at+1,Arc::new(||false)).unwrap();assert_eq!(s.bytes(&p),bytes);
 let mut old:crate::pet_runtime::authority::GrantEnvelope=serde_json::from_slice(&bytes).unwrap();old.body.schema_version=19;assert!(!old.body.valid());
}
#[test]fn branch_completed_child_reconciles_observed_spend_without_refunding_its_consumed_call(){
 let s=Setup::new();let(p,_source,r)=source(&s,"ai_lmstudio");let q=queued(&s,&r);let(g,o)=crate::pet_runtime::deterministic_runtime_tests::owned(&s.f,&s.a,&q,&s.main);let step=&g.plans[0].steps[0];let target=Arc::new(Target::capture(&s.config,&s.settings,&r.envelope().origin.pet_id).unwrap());let now=crate::assistant_memory::now();let approved=o.review_message(&g,&g.plans[0].id,&step.id,"settled-funded-reply".into(),target,now).unwrap().approve(&o,&g,&s.config,&s.settings,now,Arc::new(||true)).unwrap();let reply=o.send_message(&g,&approved,crate::assistant_memory::now(),||s.observe()).unwrap();let complete=o.verify_native_goal(&current_store(&s),&g).unwrap().completion.unwrap().record;
 assert!(review(&s,&p,&r,BranchAction::Reconcile).is_err());let proof=o.drain(DrainOutcome::Confirmed).unwrap();current_store(&s).drain_owned(&s.a,&proof,crate::assistant_memory::now()).unwrap();
 let c=review(&s,&p,&r,BranchAction::Reconcile).unwrap();let v=c.confirm(crate::assistant_memory::now(),Arc::new(||true)).unwrap().view;assert_eq!(v.consumed.as_ref().unwrap().tool_calls,1);assert!(v.consumed.as_ref().unwrap().output_bytes>0);assert_eq!(v.held.unwrap(),Allowance::default());assert_eq!(v.unknown.unwrap(),Allowance::default());assert_eq!(v.remaining.unwrap().tool_calls,4);assert!(s.a.observe_native_completed_goal(&complete).is_ok());assert_eq!(o.send_message(&g,&approved,r.envelope().deadline_at+1,||Err(model::Error::Conflict)).unwrap(),reply);
 let bytes=s.bytes(&p);let restart=Authority::existing(&s.f.path.join("authority")).unwrap().prepare_delegation_branch(p.clone(),&p.admissions[0].spec.decision_id,&r.envelope().message_id,BranchAction::Reconcile,crate::assistant_memory::now()).unwrap();restart.confirm(r.envelope().deadline_at+1,Arc::new(||false)).unwrap();assert_eq!(s.bytes(&p),bytes);
}
#[test]fn branch_orphan_binding_cancels_issued_intent_before_any_zero_io_settlement_and_prevents_late_queue(){
 let s=Setup::new();let(p,_source,r)=source(&s,"ai_lmstudio");let g=own_draft(&s,&r);let a=approved(&s,&g,child_budget(&r),nonce().unwrap());let cert=s.a.certify(&a,&g,crate::assistant_memory::now()).unwrap();assert!(review(&s,&p,&r,BranchAction::Reconcile).is_err());
 let c=review(&s,&p,&r,BranchAction::Cancel).unwrap();let before=s.bytes(&p);assert!(c.confirm(crate::assistant_memory::now(),Arc::new(||false)).is_err());assert_eq!(before,s.bytes(&p));let v=c.confirm(crate::assistant_memory::now(),Arc::new(||true)).unwrap().view;assert_eq!(v.held.unwrap().tool_calls,1);assert!(current_store(&s).enqueue_certified(&cert,crate::assistant_memory::now()).is_err());assert!(current_store(&s).read_control(&g.id,&g.spec.owner.pet_id).unwrap().admissions.is_empty());
 let settled=review(&s,&p,&r,BranchAction::Reconcile).unwrap().confirm(crate::assistant_memory::now(),Arc::new(||true)).unwrap().view;assert_eq!(settled.held.unwrap(),Allowance::default());assert_eq!(settled.consumed.unwrap(),Allowance::default());assert_eq!(settled.remaining.unwrap().tool_calls,5);assert!(matches!(&settled.reservations[0].state,Branch::Settled{settlement,..}if settlement.closure==crate::pet_runtime::delegation::Closure::RevokedNeverClaimed));
}
#[test]fn branch_unknown_effect_keeps_full_output_and_call_after_worker_drain(){
 let s=Setup::new();let(p,_source,r)=source(&s,"ai_lmstudio");let q=queued(&s,&r);let(g,o)=crate::pet_runtime::deterministic_runtime_tests::owned(&s.f,&s.a,&q,&s.main);let row=&g.admissions[0];let now=crate::assistant_memory::now();let attempt=Attempt{id:nonce().unwrap(),request_id:"uncertain-funded-effect".into(),input_hash:"a".repeat(64),kind:AttemptKind::Tool,output_reserved:512,phase:AttemptPhase::Reserved,accepted_output:None,reserved_at:now,started_at:None,finished_at:None};
 s.a.reserve_attempt(&row.spec,row.proof.as_ref().unwrap(),o.lease(),&attempt,now).unwrap();s.a.start_attempt(&row.spec,row.proof.as_ref().unwrap(),o.lease(),&attempt,now).unwrap();s.a.finish_attempt(&row.spec,row.proof.as_ref().unwrap(),o.lease(),&attempt,None,now).unwrap();review(&s,&p,&r,BranchAction::Cancel).unwrap().confirm(now,Arc::new(||true)).unwrap();project_cancel(&s,&g);let drain=o.drain(DrainOutcome::Confirmed).unwrap();current_store(&s).drain_owned(&s.a,&drain,crate::assistant_memory::now()).unwrap();
 let v=review(&s,&p,&r,BranchAction::Reconcile).unwrap().confirm(crate::assistant_memory::now(),Arc::new(||true)).unwrap().view;assert_eq!(v.consumed.unwrap(),Allowance::default());assert_eq!(v.unknown.as_ref().unwrap(),&Allowance{model_calls:0,tool_calls:1,output_bytes:512});assert_eq!(v.held.unwrap(),v.unknown.unwrap());assert_eq!(v.remaining.unwrap().tool_calls,4);
}
#[test]fn branch_cancel_lost_ack_reuses_canonical_intent_and_never_refunds_from_staged_child(){
 for fault in [Fault::BeforeGrantPublish,Fault::AfterGrantPublish]{let s=Setup::new();let(p,_source,r)=source(&s,"ai_lmstudio");let g=own_draft(&s,&r);let a=approved(&s,&g,child_budget(&r),nonce().unwrap());s.a.certify(&a,&g,crate::assistant_memory::now()).unwrap();let path=s.f.path.join("authority");let mut control=Authority::existing(&path).unwrap();control.fault=fault;let c=control.prepare_delegation_branch(p.clone(),&p.admissions[0].spec.decision_id,&r.envelope().message_id,BranchAction::Cancel,crate::assistant_memory::now()).unwrap();assert!(c.confirm(crate::assistant_memory::now(),Arc::new(||true)).is_err());
 let retry=review(&s,&p,&r,BranchAction::Cancel).unwrap();let v=retry.confirm(crate::assistant_memory::now(),Arc::new(||true)).unwrap().view;assert!(matches!(v.reservations[0].state,Branch::CancelRequested{..}));assert_eq!(v.held.unwrap().tool_calls,1);
 // Keep unresolved staged records visible. In a pre-publication failure the
 // extra image is in the PARENT; child remains independently provable unused.
 let settle=review(&s,&p,&r,BranchAction::Reconcile).unwrap();settle.confirm(crate::assistant_memory::now(),Arc::new(||true)).unwrap();
 let raw=std::fs::read(path.join(format!("{}.json",a.spec().decision_id))).unwrap();std::fs::write(path.join(format!(".grant-{}",nonce().unwrap())),raw).unwrap();assert!(review(&s,&p,&r,BranchAction::Reconcile).is_err());
 }
}
